from typing import Any, Literal, overload

import numpy as np
from numpy.typing import NDArray

"""Note: This code was almost entirely generated by Claude code"""

"""Vectorised unpacking of 32-bit packed normal/tangent data using NumPy.

Bit layout (see `normal_tangent.py` for the scalar reference implementation):
    0-9    normal X, octahedral, round(x * 511) + 512
    10-19  normal Y, octahedral, round(y * 511) + 512
    20-27  tangent angle value, round(min(|sin|, |cos|) * sqrt(2) * 255)
    28     sin sign (1 = positive)
    29     cos sign (1 = positive)
    30     which of sin/cos was stored (1 = sin, 0 = cos)
    31     bitangent handedness (1 = +1, 0 = -1)
"""

F32Array = NDArray[np.float32]
U32Array = NDArray[np.uint32]
IntArray = NDArray[np.integer[Any]]

_SQRT2 = np.float32(np.sqrt(2.0))


def _normalize(v: F32Array) -> F32Array:
    """Normalize each row of an (N, 3) array."""
    length = np.sqrt(np.einsum("ij,ij->i", v, v))
    result: F32Array = (v / length[:, None]).astype(np.float32)
    return result


def _sign_where_positive(bits: IntArray) -> F32Array:
    """Map 1 -> +1.0 and 0 -> -1.0."""
    return (bits.astype(np.float32) * 2.0 - 1.0).astype(np.float32)


@overload
def unpack(packed: U32Array, calc_tangents: Literal[False]) -> F32Array: ...


@overload
def unpack(
    packed: U32Array, calc_tangents: Literal[True] = True
) -> tuple[F32Array, F32Array]: ...


def unpack_octohedral(packed: U32Array, calc_tangents: bool = True) -> F32Array | tuple[F32Array, F32Array]:
    """Decode a 1D array of N packed uint32 values.

    Returns
    -------
    normals
        (N, 3) float32 array of unit normals.
    tangents (if calc_tangents is True)
        (N, 4) float32 array; xyz is the unit tangent and w is the bitangent handedness (+1.0 or -1.0).
    """

    xi = (packed & 0x3FF).astype(np.float32)
    yi = ((packed >> 10) & 0x3FF).astype(np.float32)

    # --- octahedral normal ---
    x = (xi - 512.0) / 511.0
    y = (yi - 512.0) / 511.0
    z = 1.0 - np.abs(x) - np.abs(y)
    fold = z < 0.0
    sign_x = np.where(x >= 0.0, 1.0, -1.0).astype(np.float32)
    sign_y = np.where(y >= 0.0, 1.0, -1.0).astype(np.float32)
    fx = (1.0 - np.abs(y)) * sign_x
    fy = (1.0 - np.abs(x)) * sign_y
    x = np.where(fold, fx, x)
    y = np.where(fold, fy, y)
    normals = _normalize(np.stack((x, y, z), axis=1).astype(np.float32))

    if not calc_tangents:
        return normals

    tq = ((packed >> 20) & 0xFF).astype(np.float32)
    sin_sign = _sign_where_positive((packed >> 28) & 1)
    cos_sign = _sign_where_positive((packed >> 29) & 1)
    stored_sin = ((packed >> 30) & 1).astype(bool)
    handedness = _sign_where_positive((packed >> 31) & 1)

    # --- tangent angle -> (cos, sin) ---
    small = tq / (_SQRT2 * 255.0)  # the smaller of |sin| and |cos|
    large = np.sqrt(np.maximum(0.0, 1.0 - small * small))
    sin_v = np.where(stored_sin, small, large) * sin_sign
    cos_v = np.where(stored_sin, large, small) * cos_sign

    # --- tangent frame: ref is +Y if |n.y| < |n.z| else -Z ---
    nx, ny, nz = normals[:, 0], normals[:, 1], normals[:, 2]
    use_y = np.abs(ny) < np.abs(nz)
    zeros = np.zeros_like(nx)
    ref = np.stack(
        (zeros, np.where(use_y, 1.0, 0.0), np.where(use_y, 0.0, -1.0)),
        axis=1,
    ).astype(np.float32)
    a = _normalize(np.cross(ref, normals).astype(np.float32))
    b = np.cross(a, normals).astype(np.float32)

    tangent_xyz = _normalize(
        (cos_v[:, None] * a + sin_v[:, None] * b).astype(np.float32)
    )
    tangents = np.concatenate((tangent_xyz, handedness[:, None]), axis=1)
    return normals, tangents
